        let kind: Int32
        let request: Int32
        let mirror: ChromiumHostOp

        init(_ kind: Int32, _ request: Int32, _ mirror: ChromiumHostOp) {
            self.kind = kind
            self.request = request
            self.mirror = mirror
        }
    }

    /// The pseudo event `attach` as a refresh kind (event kinds are >= 0).
    static let attachEvent: Int32 = -1
    static let refreshes: [Refresh] = [
        Refresh(-1, -1, .forkAPIVersion),  // attach
        Refresh(-1, -1, .placeholderSupported),  // attach
