        Refresh(2, -1, .rendererClientIDs),  // CMUX_SHIM_AFTER_CREATED
        Refresh(4, -1, .rendererClientIDs),  // CMUX_SHIM_ADDRESS
        Refresh(9, -1, .rendererClientIDs),  // CMUX_SHIM_LOAD_END
        Refresh(23, -1, .rendererClientIDs),  // CMUX_SHIM_RENDER_TERMINATED
        Refresh(67, -1, .rendererClientIDs),  // CMUX_SHIM_FRAME_RENDERERS
        Refresh(3, -1, .rendererClientIDs),  // CMUX_SHIM_BEFORE_CLOSE
        Refresh(-1, -1, .extLoadLaterSupported),  // attach
    ]

    /// The mirrors an event of `kind` with `request` refreshes, in table order.
    static func mirrors(refreshedByKind kind: Int32, request: Int32) -> [ChromiumHostOp] {
        refreshes.compactMap { $0.kind == kind && ($0.request < 0 || $0.request == request) ? $0.mirror : nil }
    }
}

/// `cmux_shim_event_kind_t`, as the host forwards it in an `eventOp` frame.
nonisolated enum ChromiumHostEventKind: Int32, CaseIterable, Sendable {
    case contextInitialized = 1, afterCreated = 2, beforeClose = 3, address = 4, title = 5, favicon = 6
    case loadingState = 7, loadStart = 8, loadEnd = 9, loadError = 10, progress = 11, fullscreen = 12
    case devToolsResult = 13, findResult = 14, closeRequested = 15, tabEvent = 16, popup = 17, reply = 18
    case contextMenu = 19, devToolsWillOpen = 20, devToolsOpened = 21, devToolsClosed = 22, renderTerminated = 23
    case renderUnresponsive = 24, renderResponsive = 25, chromeCommand = 26, navigationReroute = 27
    case keyUnhandled = 28, installPrompt = 29, omniboxSuggestions = 30, takeFocus = 31, devToolsEvent = 32
    case prefChanged = 33, downloadStarted = 34, downloadProgress = 35, downloadDone = 36, authCallback = 37
    case localFileHandoff = 38, bookmarksEvent = 39, externalURL = 40, permissionPrompt = 41
    case permissionDismissed = 42, passwordPrompt = 43, beforeUnloadDialog = 44, beforeUnloadDismissed = 45
    case pageResource = 46, pageDragEnter = 47, fileDialog = 48, cursor = 54, dragOperation = 55, tooltip = 57
    case popupMenu = 58, popupMenuHide = 59, suggestions = 60, colorChooser = 61, deviceChooser = 62
    case desktopMedia = 63, subframeRenderer = 64, lock = 65, windowRequestResult = 66, frameRenderers = 67
    case pageMessage = 49, evaluateResult = 50, createFailed = 51, widgetContext = 52, widgetGone = 53
    case wheelAck = 56, helperExit = 68

    /// The mirrors this event refreshes; the host pushes them before the event. `request` is the
    /// event's request (CMUX_SHIM_TAB_EVENT's sub-kind).
    func refreshedMirrors(request: Int32) -> [ChromiumHostOp] {
        ChromiumHostOp.mirrors(refreshedByKind: rawValue, request: request)
    }

    /// One event: `cmux_shim_event_fn`'s arguments. A kind this build does not know still decodes.
    nonisolated struct Record: Equatable, Sendable {
        let rawKind: Int32
        let browser: Int32
        let request: Int32
        let a: Int64
        let b: Int64
        let s1: String
        let s2: String

        var kind: ChromiumHostEventKind? { ChromiumHostEventKind(rawValue: rawKind) }

        typealias Reader = (ChromiumHostOp.WireType) throws(ChromiumHostOp.WireError) -> ChromiumHostOp.Value

        init(reading next: Reader) throws(ChromiumHostOp.WireError) {
            rawKind = try Self.int32(next(.int32))
            browser = try Self.int32(next(.int32))
            request = try Self.int32(next(.int32))
            a = try Self.int64(next(.int64))
            b = try Self.int64(next(.int64))
            s1 = try Self.string(next(.string))
            s2 = try Self.string(next(.string))
        }

        private static func int32(_ value: ChromiumHostOp.Value) throws(ChromiumHostOp.WireError) -> Int32 {
            guard case .int32(let number) = value else { throw .malformed }
            return number
        }

        private static func int64(_ value: ChromiumHostOp.Value) throws(ChromiumHostOp.WireError) -> Int64 {
            guard case .int64(let number) = value else { throw .malformed }
            return number
        }

        private static func string(_ value: ChromiumHostOp.Value) throws(ChromiumHostOp.WireError) -> String {
            guard case .string(let text) = value else { throw .malformed }
            return text ?? ""
        }
    }
}
